custom_css:
.ca-logo {
  display: block;
  max-height: 56px;
  width: auto;
  margin: 0 auto 1.25rem;
  object-fit: contain;
}

.web-form-container {
  --ca-ink: #16211c;
  --ca-ink-soft: #5c6b64;
  --ca-line: #dfe4e0;
  --ca-accent: #1f4034;
  --ca-accent-soft: #eef2ef;
  --ca-surface: #ffffff;
  --ca-page: #f7f8f6;
  max-width: 800px;
  margin: 0 auto;
  color: var(--ca-ink);
}

.web-form-container .web-form-header {
  border-bottom: 1px solid var(--ca-line);
  padding-bottom: 1.25rem;
  margin-bottom: 2rem;
}

.web-form-container .web-form-head .title,
.web-form-container h1 {
  font-weight: 700;
  font-size: 1.75rem;
  letter-spacing: -0.02em;
  color: var(--ca-ink);
}

.web-form-container .web-form-introduction p {
  color: var(--ca-ink-soft);
  font-size: 0.95rem;
  line-height: 1.55;
  margin-bottom: 0.4rem;
}

.web-form-wrapper {
  counter-reset: ca-section;
}

.web-form-wrapper .section-head,
.web-form-wrapper .form-section .section-head {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--ca-accent);
  padding-bottom: 0.6rem;
  margin-bottom: 1.1rem;
  border-bottom: 1px solid var(--ca-line);
}

.web-form-wrapper .form-section {
  counter-increment: ca-section;
  background: var(--ca-surface);
  border: 1px solid var(--ca-line);
  border-radius: 10px;
  padding: 1.6rem 1.6rem 0.85rem;
  margin-bottom: 1.4rem;
  box-shadow: 0 1px 2px rgba(22, 33, 28, 0.04);
}

.web-form-wrapper .section-head::before {
  content: counter(ca-section);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.5rem;
  height: 1.5rem;
  flex: 0 0 auto;
  border-radius: 50%;
  background: var(--ca-accent);
  color: #fff;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0;
  text-transform: none;
}

.web-form-wrapper .control-label {
  font-weight: 500;
  color: var(--ca-ink);
}

.web-form-wrapper .help-box,
.web-form-wrapper .form-control + .help-box {
  color: var(--ca-ink-soft);
  font-size: 0.8125rem;
  line-height: 1.45;
}

.web-form-wrapper .form-control {
  border: 1px solid var(--ca-line);
  border-radius: 6px;
  background: var(--ca-page);
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.web-form-wrapper .form-control:focus {
  border-color: var(--ca-accent);
  background: var(--ca-surface);
  box-shadow: 0 0 0 3px var(--ca-accent-soft);
  outline: none;
}

.web-form-footer {
  border-top: 1px solid var(--ca-line);
  padding-top: 1.25rem;
  margin-top: 0.5rem;
}

.web-form-footer .submit-btn {
  background: var(--ca-accent);
  border-color: var(--ca-accent);
  font-weight: 600;
  padding: 0.6rem 1.6rem;
  font-size: 0.9rem;
  border-radius: 6px;
}

.web-form-footer .submit-btn:hover {
  background: #163027;
  border-color: #163027;
}

.web-form-footer .submit-btn:focus-visible {
  outline: 2px solid var(--ca-accent);
  outline-offset: 2px;
}

.web-form-footer .discard-btn {
  border-radius: 6px;
  font-weight: 500;
  color: var(--ca-ink-soft);
  border-color: var(--ca-line);
}

.ca-license-warning {
  margin-top: 0.4rem;
  font-size: 0.8125rem;
  color: #8a5a00;
}

@media (max-width: 767px) {
  .web-form-container {
    max-width: 100%;
  }
  .web-form-wrapper .form-section {
    padding: 1.1rem 1.1rem 0.4rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  .web-form-wrapper .form-control {
    transition: none;
  }
}

/* Currency inputs show their symbol. Frappe only renders the symbol on
   read-only/formatted values, never inside an editable input, so the $ on
   these two Currency fields comes from here. */
.web-form-wrapper .frappe-control[data-fieldname="requested_limit"] .control-input,
.web-form-wrapper .frappe-control[data-fieldname="expected_monthly_revenue"] .control-input {
  position: relative;
}

.web-form-wrapper .frappe-control[data-fieldname="requested_limit"] .control-input::before,
.web-form-wrapper .frappe-control[data-fieldname="expected_monthly_revenue"] .control-input::before {
  content: "$";
  position: absolute;
  top: 50%;
  left: 14px;
  transform: translateY(-50%);
  line-height: 1;
  color: var(--ca-ink-soft, #5c6b64);
  pointer-events: none;
  z-index: 2;
}

.web-form-wrapper .frappe-control[data-fieldname="requested_limit"] .form-control,
.web-form-wrapper .frappe-control[data-fieldname="expected_monthly_revenue"] .form-control {
  /* infix_portal.css forces `padding: 8px 14px !important` on .form-control,
     .input-with-feedback and input[type="text"], so making room for the symbol
     has to outrank it. Without !important the $ lands on top of the digits. */
  padding-left: 30px !important;
}
